import{_ as o,o as t,c as a,ag as s}from"./chunks/framework.8tqBsFWt.js";const u=JSON.parse('{"title":"Secret rotation runbook","description":"","frontmatter":{},"headers":[],"relativePath":"operations/secret-rotation.md","filePath":"operations/secret-rotation.md"}'),n={name:"operations/secret-rotation.md"};function i(r,e,l,c,d,h){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="secret-rotation-runbook" tabindex="-1">Secret rotation runbook <a class="header-anchor" href="#secret-rotation-runbook" aria-label="Permalink to &quot;Secret rotation runbook&quot;">​</a></h1><p>Use this procedure whenever a secret is exposed — if it appears in a log, a transcript, a shared screen, or a repository — or on a periodic cadence, or when someone with access leaves. The same steps apply regardless of how the exposure happened.</p><h2 id="when-to-rotate" tabindex="-1">When to rotate <a class="header-anchor" href="#when-to-rotate" aria-label="Permalink to &quot;When to rotate&quot;">​</a></h2><p>Rotate any secret that has been:</p><ul><li>Printed to a terminal or log that was shared or recorded</li><li>Committed to version control (even briefly)</li><li>Sent over a channel that isn&#39;t encrypted end-to-end</li><li>Viewed by someone who should not have access</li></ul><p>When in doubt, rotate. The cost is usually a Railway redeploy (~30 seconds); the cost of not rotating can be far higher.</p><p><strong>Cadence:</strong> rotate long-lived secrets roughly quarterly, and immediately on suspected compromise or staff offboarding. Guidance, not a hard policy.</p><p><strong>Recommended order when rotating everything at once:</strong> do the disruptive ones in a maintenance window — <code>DATABASE_URL</code> / <code>MIGRATION_DATABASE_URL</code> (brief outage) and <code>CONSOLE_SESSION_SECRET</code> (logs every console user out). The rest (Anthropic, OAuth, Slack, error-reporter) are isolated and can be done any time. After each, run the <strong>Sanity sweep</strong> at the bottom.</p><p>Secrets never live in code — they&#39;re Railway environment variables, the tenants file, or the relevant provider console. &quot;Update in VERA&quot; almost always means <strong>Railway service → Variables → edit → Save</strong> (which auto-redeploys), except per-tenant Slack creds (tenants file / <code>/admin</code>).</p><hr><h2 id="_1-admin-secret" tabindex="-1">1. <code>ADMIN_SECRET</code> <a class="header-anchor" href="#_1-admin-secret" aria-label="Permalink to &quot;1. `ADMIN_SECRET`&quot;">​</a></h2><p>Gates <code>/admin</code> and the <code>/status*</code> dashboards.</p><ol><li>Generate: <code>node -e &quot;console.log(require(&#39;crypto&#39;).randomBytes(24).toString(&#39;base64&#39;))&quot;</code></li><li>Update on Railway → <code>ADMIN_SECRET</code> → Save.</li><li><strong>Blast radius:</strong> <code>/admin</code> and <code>/status</code> reject the old secret immediately; no user-facing impact.</li><li>Verify: <code>/admin</code> and <code>/status</code> accept the new secret.</li></ol><hr><h2 id="_2-database-url-supabase-vera-app-role" tabindex="-1">2. <code>DATABASE_URL</code> (Supabase <code>vera_app</code> role) <a class="header-anchor" href="#_2-database-url-supabase-vera-app-role" aria-label="Permalink to &quot;2. `DATABASE_URL` (Supabase `vera_app` role)&quot;">​</a></h2><p>Runtime connection used by <code>lib/pg.js</code>. The role is <code>vera_app</code> — NOBYPASSRLS, DML grants only. Do <strong>not</strong> reset the master <code>postgres</code> password here.</p><ol><li>Supabase → Settings → Database → reset the <code>vera_app</code> role password.</li><li>Copy the new connection string (pooler mode).</li><li>Update on Railway → <code>DATABASE_URL</code> → Save.</li><li><strong>Blast radius:</strong> full outage until the redeploy picks up the new value (the app can&#39;t reach Postgres).</li><li>Verify: a console read (e.g. the project list) returns data. Confirm the old string fails: <code>psql &quot;old-string&quot; -c &quot;SELECT 1&quot;</code>.</li></ol><hr><h2 id="_3-migration-database-url-supabase-postgres-role" tabindex="-1">3. <code>MIGRATION_DATABASE_URL</code> (Supabase <code>postgres</code> role) <a class="header-anchor" href="#_3-migration-database-url-supabase-postgres-role" aria-label="Permalink to &quot;3. `MIGRATION_DATABASE_URL` (Supabase `postgres` role)&quot;">​</a></h2><p>Privileged connection used by <code>scripts/start.js</code> to run migrations at boot. Role <code>postgres</code> — bypasses RLS, manages <code>pgmigrations</code>.</p><ol><li>Supabase → Settings → Database → reset the <code>postgres</code> role password.</li><li>Copy the new connection string.</li><li>Update on Railway → <code>MIGRATION_DATABASE_URL</code> → Save.</li><li><strong>Blast radius:</strong> runtime unaffected; only the <strong>next deploy&#39;s</strong> migrate step fails if this is stale.</li><li>Verify: next deploy&#39;s boot log shows the migrate step succeeding. Update any local <code>.env</code> used for <code>npm run migrate:up</code>.</li></ol><hr><h2 id="_4-anthropic-api-key" tabindex="-1">4. <code>ANTHROPIC_API_KEY</code> <a class="header-anchor" href="#_4-anthropic-api-key" aria-label="Permalink to &quot;4. `ANTHROPIC_API_KEY`&quot;">​</a></h2><p>Used for box-2 (analytical) model calls. Box-1 deterministic paths and the entire console do <strong>not</strong> call the model.</p><ol><li>Rotate in the Anthropic console (create a new key, then revoke the old).</li><li>Update on Railway → <code>ANTHROPIC_API_KEY</code> → Save.</li><li><strong>Blast radius:</strong> analytical Slack replies fail until updated; deterministic logging/reads and all console pages are unaffected.</li><li>Verify: <code>/status</code> Anthropic check goes green (it records the last successful <code>messages.create</code>).</li></ol><hr><h2 id="_5-console-session-secret" tabindex="-1">5. <code>CONSOLE_SESSION_SECRET</code> <a class="header-anchor" href="#_5-console-session-secret" aria-label="Permalink to &quot;5. `CONSOLE_SESSION_SECRET`&quot;">​</a></h2><p>HMAC key for console session cookies, magic-link tokens, and OAuth state cookies (<code>lib/console/auth.js</code>). <strong>High blast radius — rotate deliberately.</strong></p><ol><li>Generate: <code>node -e &quot;console.log(require(&#39;crypto&#39;).randomBytes(32).toString(&#39;hex&#39;))&quot;</code></li><li>Update on Railway → <code>CONSOLE_SESSION_SECRET</code> → Save.</li><li><strong>Blast radius:</strong> <strong>every active console session is invalidated and all outstanding magic links stop working</strong> — everyone must sign in again. Any OAuth flow in flight at the moment of rotation fails and must be restarted. If this var is ever <em>unset</em>, <code>/console*</code> returns 503 (fail-closed).</li><li>Verify: sign in to <code>/console</code> fresh (OAuth or magic link) and confirm a session is established.</li></ol><hr><h2 id="_6-google-oauth-client-id-google-oauth-client-secret" tabindex="-1">6. <code>GOOGLE_OAUTH_CLIENT_ID</code> / <code>GOOGLE_OAUTH_CLIENT_SECRET</code> <a class="header-anchor" href="#_6-google-oauth-client-id-google-oauth-client-secret" aria-label="Permalink to &quot;6. `GOOGLE_OAUTH_CLIENT_ID` / `GOOGLE_OAUTH_CLIENT_SECRET`&quot;">​</a></h2><p>Google sign-in for the console. Only the <strong>secret</strong> rotates day-to-day; the client ID changes only if you recreate the OAuth client.</p><ol><li>Google Cloud console → APIs &amp; Services → Credentials → the OAuth client → rotate the client secret.</li><li>Update on Railway → <code>GOOGLE_OAUTH_CLIENT_SECRET</code> (and <code>..._CLIENT_ID</code> if it changed) → Save.</li><li><strong>Blast radius:</strong> &quot;Sign in with Google&quot; fails until updated; existing console sessions survive. If both vars are unset, the Google button simply doesn&#39;t render.</li><li>Verify: the login page shows the Google button and a Google sign-in completes.</li></ol><hr><h2 id="_7-ms-oauth-client-id-ms-oauth-client-secret" tabindex="-1">7. <code>MS_OAUTH_CLIENT_ID</code> / <code>MS_OAUTH_CLIENT_SECRET</code> <a class="header-anchor" href="#_7-ms-oauth-client-id-ms-oauth-client-secret" aria-label="Permalink to &quot;7. `MS_OAUTH_CLIENT_ID` / `MS_OAUTH_CLIENT_SECRET`&quot;">​</a></h2><p>Microsoft (Azure AD / Entra) sign-in. Same shape as Google.</p><ol><li>Azure portal → App registrations → the app → Certificates &amp; secrets → new client secret; remove the old.</li><li>Update on Railway → <code>MS_OAUTH_CLIENT_SECRET</code> (and <code>..._CLIENT_ID</code> if it changed) → Save.</li><li><strong>Blast radius:</strong> &quot;Sign in with Microsoft&quot; fails until updated; existing sessions survive.</li><li>Reminder: the callback URI registered in Azure must be <code>${CONSOLE_BASE_URL}/console/auth/microsoft/callback</code>.</li><li>Verify: a Microsoft sign-in completes.</li></ol><hr><h2 id="_8-error-reporter-github-token" tabindex="-1">8. <code>ERROR_REPORTER_GITHUB_TOKEN</code> <a class="header-anchor" href="#_8-error-reporter-github-token" aria-label="Permalink to &quot;8. `ERROR_REPORTER_GITHUB_TOKEN`&quot;">​</a></h2><p>GitHub PAT with <code>repo</code> scope on <code>talktalkmake/VERA</code>, used to auto-file issues. Must be <strong>unset / no-op in dev and test</strong>.</p><ol><li>GitHub → Settings → Developer settings → Personal access tokens → revoke the old, create a new one with <code>repo</code> scope.</li><li>Update on Railway → <code>ERROR_REPORTER_GITHUB_TOKEN</code> → Save.</li><li><strong>Blast radius:</strong> automatic issue filing stops until updated; the app is otherwise unaffected (the reporter is fire-and-forget and never blocks responses).</li><li>Verify: a subsequent real error files/updates an issue (or test in staging).</li></ol><hr><h2 id="_9-per-tenant-slack-credentials" tabindex="-1">9. Per-tenant Slack credentials <a class="header-anchor" href="#_9-per-tenant-slack-credentials" aria-label="Permalink to &quot;9. Per-tenant Slack credentials&quot;">​</a></h2><p>Each tenant has its own <code>slack_bot_token</code> (<code>xoxb-…</code>) and <code>slack_app_token</code> (<code>xapp-…</code>), stored in the tenants file (<code>TENANTS_FILE</code> / <code>tenants.dev.json</code>) and editable in <code>/admin</code>. These are <strong>not</strong> global env vars.</p><ol><li>Rotate in the Slack app configuration (the distributed app <code>A0AE27UD6H3</code>, or the tenant&#39;s own app) → regenerate the bot token / app-level token.</li><li>Update in VERA via <code>/admin</code> (the tenant editor) or by editing the tenants file and reloading.</li><li><strong>Blast radius:</strong> that one tenant&#39;s Slack bot goes offline until updated; <strong>other tenants are unaffected</strong> (credentials are per-tenant).</li><li>Verify: <code>/status</code> Slack-socket check for that tenant is green, and the bot replies to a DM.</li></ol><hr><h2 id="sanity-sweep" tabindex="-1">Sanity sweep <a class="header-anchor" href="#sanity-sweep" aria-label="Permalink to &quot;Sanity sweep&quot;">​</a></h2><p>Run after rotating anything:</p><ul><li>[ ] <code>/status</code> shows green for Postgres and Anthropic</li><li>[ ] A console page loads and a fresh sign-in works (if <code>CONSOLE_SESSION_SECRET</code> or an OAuth secret was rotated)</li><li>[ ] <code>/admin</code> accepts the current <code>ADMIN_SECRET</code></li><li>[ ] The bot replies to a Slack DM on at least one tenant (if any Slack/DB secret was rotated)</li><li>[ ] The next deploy&#39;s boot log shows migrations applying cleanly (if <code>MIGRATION_DATABASE_URL</code> was rotated)</li></ul>',49)])])}const g=o(n,[["render",i]]);export{u as __pageData,g as default};
